// game set up
scene.setBackgroundColor(13)
game.showLongText("Guess the secret number!", DialogLayout.Center)

// 1 digit number
let randNum1 = randint(0, 9)
let randNum2 = randint(0, 9)

let userGuess = game.askForNumber("Pick a number 0-9", 1)

if (userGuess == randNum1) {
    game.showLongText("" + userGuess + " is correct! You're moving on to the next round!", DialogLayout.Center)
} else {
    game.showLongText("Sorry, the secret numbers were " + randNum1 + " or " + randNum2, DialogLayout.Center)
    game.gameOver(false)
}

